import re, json, sys, os
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
OUT = os.environ.get('LAYERS_OUT', os.path.join(os.getcwd(), 'src/mie/layers/Layers.tsx'))   # default: ./src/mie/layers/Layers.tsx
from kit import *
import scene

def camel(m):
    p = m.group(1).split('-'); return p[0] + ''.join(x.title() for x in p[1:]) + '='
def jsx(s):
    s = re.sub(r'\b([a-z]+(?:-[a-z]+)+)=', camel, s)
    return s.replace('xlink:href', 'xlinkHref')

doc = Doc(1)
layers, meta = scene.build(doc, True)
out = ["import React from 'react';", '',
       '/** GENERATED by frame/emit_ts.py - 100% SVG. Static art layers of the noodle-stall scene. */',
       'export const Defs: React.FC = () => (', '  <defs>' + jsx(''.join(doc.defs)) + '</defs>', ');', '',
       'export const LAYERS: Record<string, React.FC> = {']
for name, lst in layers:
    body = jsx(''.join(lst))
    out.append(f"  {name}: () => (<g>{body}</g>),")
out.append('};')
out.append('export const META: Record<string, [number, number]> = ' + json.dumps(meta) + ';')
os.makedirs(os.path.dirname(OUT), exist_ok=True)
open(OUT, 'w').write('\n'.join(out))
print('layers', len(layers), 'bytes', sum(len(x) for x in out))
